package io.github.polestarcn.companion;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
/** Private local energy observations. No network, maps, identifiers or third-party chart SDK. */
public final class EnergyActivity extends Activity {
 private LinearLayout page,results;private String vehicle;private int range=1,metric=0,generation;private boolean ac=true,dead;private long endTime;private int ink,muted;private final Handler main=new Handler(Looper.getMainLooper());
 private String tr(String a,String b){return AppPreferences.tr(this,a,b);}private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(ink);t.setPadding(12,8,12,8);return t;}
 private Button button(String value,Runnable click){Button b=new Button(this);b.setTextColor(ink);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(PsaDesign.surface(AppPreferences.dark(this))));b.setText(value);b.setOnClickListener(v->{Haptics.tap(this);click.run();});return b;}
 protected void attachBaseContext(Context c){super.attachBaseContext(UiTypography.wrap(c));}
 public void onCreate(Bundle state){super.onCreate(state);vehicle=getIntent().getStringExtra("vehicle");if(!EnergyLog.validVehicle(vehicle))vehicle=AppPreferences.get(this,"vehicle","");if(!EnergyLog.validVehicle(vehicle))vehicle=null;if(state!=null){range=state.getInt("range",1);metric=state.getInt("metric",0);ac=state.getBoolean("ac",true);endTime=state.getLong("endTime",0);}ink=PsaDesign.ink(AppPreferences.dark(this));muted=PsaDesign.muted(AppPreferences.dark(this));ScrollView scroll=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setBackgroundColor(PsaDesign.canvas(AppPreferences.dark(this)));scroll.addView(page);setContentView(scroll);
  page.addView(button(tr("返回车况","Back to condition"),this::finish));page.addView(text(tr("行驶 / 驻车空调能耗","Driving / parked climate energy"),22));
  HelpDisclosure.add(page,this,tr("估算说明","Estimate notes"),tr("电池容量可在记录设置中填写，默认71kWh。掉电包含其他负载；行驶按TM距离×均耗估算，不是独立电表。","Battery capacity is configurable (default 71kWh). Loss includes other loads; driving uses TM distance × consumption, not a separate meter."));
  page.addView(button(tr("选择本机历史车辆","Choose saved vehicle"),this::chooseVehicle));
  page.addView(button(tr("切换：空调 / 行驶","Switch: climate / driving"),()->{ac=!ac;load();}));
  Spinner periods=new Spinner(this);periods.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{tr("12H刻度 · 最近7天","12h · last 7 days"),tr("日 · 最近31天","Day · last 31 days"),tr("月 · 最近12月","Month · last 12 months"),tr("年 · 最近2年","Year · last 2 years")}){public View getView(int position,View convert,ViewGroup parent){View v=super.getView(position,convert,parent);if(v instanceof TextView)((TextView)v).setTextColor(ink);return v;}});periods.setSelection(range);periods.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){range=pos;load();}});page.addView(periods);page.addView(button(tr("选择截止日期（默认今天）","Select end date (today by default)"),this::date));
  page.addView(button(tr("曲线：总能耗 / TM均耗 / TM均速","Chart: total energy / TM consumption / speed"),()->{metric=(metric+1)%3;load();}));page.addView(button(tr("电价、保存期限与清空记录","Price, retention and clear history"),this::settings));results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);page.addView(results);load();}
 private void load(){if(results==null||dead)return;int request=++generation;results.removeAllViews();results.addView(text(tr("读取本机记录…","Loading local history…"),14));EnergyLog.WORK.execute(()->{try{String selected=vehicle;if(selected==null){List<String> ids=EnergyLog.get(this).vehicles();selected=ids.isEmpty()?null:ids.get(0);}final String loadedVehicle=selected;EnergyLog.Report report=selected==null?new EnergyLog.Report():EnergyLog.get(this).read(selected,range,endTime==0?System.currentTimeMillis():endTime);main.post(()->{if(dead||request!=generation)return;results.removeAllViews();vehicle=loadedVehicle;showCurrentTm();double kwh=ac?report.ac*EnergyLog.perPercent(this):report.drive;results.addView(text((ac?tr("驻车空调估算","Parked climate estimate"):tr("TM行驶估算","TM driving estimate"))+String.format(Locale.getDefault()," · %.2f kWh · %.2f%% · %.2f",kwh,kwh/EnergyLog.perPercent(this),kwh*EnergyLog.price(this))+tr(" 元 · 估算电费"," CNY · estimated cost"),17));results.addView(text(String.format(Locale.getDefault(),"%.1f kWh · 1%% = %.3f kWh",EnergyLog.capacity(this),EnergyLog.perPercent(this)),12));results.addView(text(tr("采样记录：","Samples: ")+report.count+tr(" · 保留"," · retention ")+EnergyLog.months(this)+tr("个月"," months"),12));results.addView(text(ac?tr("曲线：驻车空调期间电量%","Chart: battery % during stationary climate"):metric==0?tr("曲线：区间累计行驶能耗 kWh","Chart: cumulative driving kWh"):metric==1?tr("曲线：TM平均能耗 kWh/100km","Chart: TM kWh/100km"):tr("曲线：TM平均速度 km/h","Chart: TM average km/h"),14));final Chart chart=new Chart(report);chart.setVisibility(View.GONE);Button expand=button(tr("展开 / 收起曲线","Expand / collapse chart"),()->chart.setVisibility(chart.getVisibility()==View.GONE?View.VISIBLE:View.GONE));results.addView(expand);results.addView(chart,new LinearLayout.LayoutParams(-1,(int)(240*getResources().getDisplayMetrics().density)));if(report.count==0)results.addView(text(tr("暂无记录。开启后随成功刷新自动采样；不会补造历史。","No records yet. Samples follow successful refreshes; history is never fabricated."),14));});}catch(Exception e){main.post(()->{if(!dead&&request==generation){results.removeAllViews();results.addView(text(tr("记录暂不可用，请稍后重试","History unavailable. Try again."),14));}});}});}
 /** Instant TM is a trip-since-reset estimate, not history or a charging meter. */
  private void showCurrentTm(){VehicleCoordinator coordinator=VehicleCoordinator.get(this);
    VehicleSnapshot snapshot=coordinator.snapshot;
    if(coordinator.selected==null||!vehicle.equals(VehicleCoordinator.identity(coordinator.selected.vin)))snapshot=null;
    Double kwh=TmCost.kwh(snapshot,System.currentTimeMillis());
    if(kwh==null){results.addView(text(tr("当前 TM：暂无有效的实时里程与百公里能耗，请先刷新车况","Current TM: no fresh distance and consumption; refresh vehicle first"),15));return;}
    double tariff=EnergyLog.price(this);
    results.addView(text(tr("当前 TM 累计行驶估算","Current TM trip estimate")+String.format(Locale.getDefault()," · %.2f kWh",kwh),18));
    results.addView(text(tariff>0?String.format(Locale.getDefault(),"%.2f %s · %.2f %s/kWh",TmCost.cost(kwh,tariff),tr("元","CNY"),tariff,tr("元","CNY")):tr("尚未设置电价；请在下方设置元/kWh","Tariff not set; configure CNY/kWh below"),17));
    HelpDisclosure.add(results,this,tr("计算说明","Calculation notes"),tr("按本次 TM 里程 × TM 百公里均耗计算；非充电费用、非当日费用，不与历史采样累加。","Calculated from current TM distance × average consumption. Not a charging meter or daily cost; never added to sampled history."));
  }
 private void chooseVehicle(){EnergyLog.WORK.execute(()->{List<String> ids=EnergyLog.get(this).vehicles();main.post(()->{if(dead)return;if(ids.isEmpty()){Toast.makeText(this,tr("暂无本机历史记录","No local history yet"),Toast.LENGTH_SHORT).show();return;}String[] labels=new String[ids.size()];for(int i=0;i<labels.length;i++)labels[i]=tr("本机车辆 ","Saved vehicle ")+(i+1)+" · "+ids.get(i).substring(0,8);new HapticDialogBuilder(this).setTitle(tr("选择历史车辆","Choose saved vehicle")).setItems(labels,(d,w)->{vehicle=ids.get(w);load();}).setNegativeButton(tr("取消","Cancel"),null).show();});});}
 private void date(){Calendar selected=Calendar.getInstance();if(endTime>0)selected.setTimeInMillis(endTime);DatePickerDialog picker=new DatePickerDialog(this,(view,year,month,day)->{Calendar date=Calendar.getInstance();date.set(year,month,day,23,59,59);endTime=date.getTimeInMillis();load();},selected.get(Calendar.YEAR),selected.get(Calendar.MONTH),selected.get(Calendar.DAY_OF_MONTH));Calendar first=Calendar.getInstance();first.add(Calendar.MONTH,-EnergyLog.months(this));picker.getDatePicker().setMinDate(first.getTimeInMillis());picker.getDatePicker().setMaxDate(System.currentTimeMillis());picker.show();}
 private void settings(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setBackgroundColor(PsaDesign.canvas(AppPreferences.dark(this)));p.addView(text(tr("电池容量（kWh，10–200，默认71）","Battery capacity (kWh, 10–200, default 71)"),14));EditText capacity=new EditText(this);capacity.setTextColor(ink);capacity.setInputType(8194);capacity.setText(String.valueOf(EnergyLog.capacity(this)));p.addView(capacity);p.addView(text(tr("电价（元/kWh）","Price per kWh"),14));EditText price=new EditText(this);price.setTextColor(ink);price.setText(String.valueOf(EnergyLog.price(this)));price.setInputType(8194);p.addView(price);p.addView(text(tr("保存月数（1–24，12个月=1年）","Retention months (1–24; 12 = 1 year)"),14));EditText months=new EditText(this);months.setTextColor(ink);months.setInputType(2);months.setText(String.valueOf(EnergyLog.months(this)));p.addView(months);AlertDialog dialog=new HapticDialogBuilder(this).setTitle(tr("能耗记录设置","Energy history settings")).setView(p).setPositiveButton(tr("保存","Save"),null).setNegativeButton(tr("取消","Cancel"),null).setNeutralButton(tr("清空数据库","Clear database"),(d,w)->new HapticDialogBuilder(this).setMessage(tr("清空本机所有车辆的能耗记录？无法恢复。","Delete all local vehicle energy history? This cannot be undone.")).setPositiveButton(tr("清空","Delete"),(x,y)->EnergyLog.WORK.execute(()->{try{EnergyLog.get(this).clear();main.post(this::load);}catch(Exception e){main.post(()->{if(!dead)Toast.makeText(this,tr("清空未完成，请重试","Clear failed; try again"),Toast.LENGTH_LONG).show();});}})).setNegativeButton(tr("取消","Cancel"),null).show()).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{try{double cap=Double.parseDouble(capacity.getText().toString());if(!Double.isFinite(cap)||cap<10||cap>200)throw new IllegalArgumentException();double x=Double.parseDouble(price.getText().toString());int m=Integer.parseInt(months.getText().toString());if(!Double.isFinite(x)||x<0||x>100||m<1||m>24)throw new IllegalArgumentException();AppPreferences.set(this,"battery_capacity_kwh",""+cap);AppPreferences.set(this,"energy_price",""+x);AppPreferences.set(this,"energy_months",""+m);EnergyLog.WORK.execute(()->{try{EnergyLog.get(this).prune();main.post(this::load);}catch(Exception e){main.post(()->{if(!dead)Toast.makeText(this,tr("清理未完成，请重试","Cleanup failed; try again"),Toast.LENGTH_LONG).show();});}});dialog.dismiss();}catch(Exception e){months.setError(tr("容量10–200kWh，电价0–100，保存1–24个月","Capacity 10–200kWh; price 0–100; retention 1–24 months"));}});}
 protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putInt("range",range);b.putInt("metric",metric);b.putBoolean("ac",ac);b.putLong("endTime",endTime);}protected void onDestroy(){dead=true;generation++;main.removeCallbacksAndMessages(null);super.onDestroy();}
 private final class Chart extends View {
  private final Paint paint=new Paint(3);private final Double[] values;private final long[] times;private final String[] labels;private final double max;private final String axisMaximum;
  Chart(EnergyLog.Report report){super(EnergyActivity.this);setContentDescription(tr("能耗时间曲线，汇总见上方文字","Energy timeline; accessible summary above"));int n=report.points.size();values=new Double[n];times=new long[n];labels=new String[n];double total=0,limit=1;for(int i=0;i<n;i++){EnergyLog.Point point=report.points.get(i);total+=point.drive;values[i]=ac?point.soc:metric==0?total:metric==1?point.cons:point.speed;times[i]=point.t;if(values[i]!=null)limit=Math.max(limit,values[i]);if(i==0||i==n-1||i==n/2)labels[i]=android.text.format.DateFormat.format(range==0?"MM-dd HH:mm":range==1?"MM-dd":range==2?"yyyy-MM":"yyyy",point.t).toString();}max=ac?100:limit;axisMaximum=String.format(Locale.getDefault(),"%.0f",max);}
  protected void onDraw(Canvas c){super.onDraw(c);float d=getResources().getDisplayMetrics().density,left=45*d,top=16*d,w=getWidth()-left-18*d,h=getHeight()-top-48*d;paint.setColor(muted);paint.setStrokeWidth(d);c.drawLine(left,top,left,top+h,paint);c.drawLine(left,top+h,left+w,top+h,paint);paint.setTextSize(10*d);c.drawText(axisMaximum,3*d,top+10*d,paint);c.drawText("0",20*d,top+h,paint);float px=0,py=0;boolean previous=false;for(int i=0;i<values.length;i++){Double value=values[i];if(value==null){previous=false;continue;}float x=left+(values.length==1?w/2:w*(times[i]-times[0])/(float)Math.max(1,times[times.length-1]-times[0])),y=top+h-(float)(value/max)*h;paint.setColor(PsaDesign.ORANGE);paint.setStrokeWidth(2*d);if(previous)c.drawLine(px,py,x,y,paint);c.drawCircle(x,y,2*d,paint);px=x;py=y;previous=true;}paint.setColor(muted);for(int i=0;i<labels.length;i++){String label=labels[i];if(label==null)continue;float x=left+(times.length==1?w/2:w*(times[i]-times[0])/(float)Math.max(1,times[times.length-1]-times[0]));c.drawText(label,Math.max(left,Math.min(x-paint.measureText(label)/2,getWidth()-paint.measureText(label))),top+h+20*d,paint);}}
 }
}
